mapper.update:
		/*updateMasterMpIfErrorStateMain_RD_DATE_IF*/

		UPDATE ICOMPRDT  
		   SET RD_DATE = #{RD_DATE_IF}
         WHERE BUYER   = #{BUYER} 
           AND PR_NO   = #{PR_NO_B}
           AND PR_SEQ  = #{PR_SEQ_B}

		/*updateMasterMpIfErrorStateMain_RdDate_pr*/

		UPDATE ICOMPODT  
		   SET RD_DATE = #{RD_DATE_IF}
         WHERE BUYER   = #{BUYER} 
           AND PR_NO   = #{PR_NO_B}
           AND PR_SEQ  = #{PR_SEQ_B}

/*updateMasterMpIfErrorStateMain_Execute_IF_PODT*/

		UPDATE IF_PODT /* 인터페이스 주문상세내역 */
		SET CHANGE_USER_ID   = #{st_user_id}
		  , CHANGE_DATE      = TO_CHAR(SYSDATE,'YYYYMMDD')
		  , CHANGE_TIME      = TO_CHAR(SYSDATE,'HH24MISS')
		  , AGENT            = #{AGENT}
		  , DOC_TYPE         = #{DOC_TYPE}
		  , CONTRACT_NO      = #{CONTRACT_NO}
		  , CONTRACT_SEQ     = #{CONTRACT_SEQ}
		  , ADD_DATE         = #{ADD_DATE}
		  , RD_DATE          = #{RD_DATE_IF}
		  , DATE_CHANGE_HIST = SUBSTRB(SUBSTRB(DATE_CHANGE_HIST,1,350)||(CASE WHEN ADD_DATE != #{ADD_DATE} THEN '@ADD_DATE:'||ADD_DATE||'#'||CHANGE_USER_ID END)||(CASE WHEN RD_DATE != #{RD_DATE_IF} THEN '@RD_DATE:'||RD_DATE||'#'||CHANGE_USER_ID END),1,400)
		  , BUYER_ITEM_NO    = NVL(TRIM(#{BUYER_ITEM_NO}),' ')
		  , UNIT_PRICE       = NVL(#{UNIT_PRICE_IF},UNIT_PRICE)
		  , ITEM_AMT         = NVL(#{UNIT_PRICE_IF},UNIT_PRICE) * ITEM_QTY
		  , DELY_TO_LOCATION = #{DELY_TO_LOCATION}
		WHERE 1=1
		AND BUYER            = #{BUYER}
		AND LEGACY_PO_NO     = #{LEGACY_PO_NO}
		AND LEGACY_PO_SEQ    = NVL(#{LEGACY_PO_SEQ},' ')
		AND BUYER_ITEM_NO    = NVL(#{BUYER_ITEM_NO},' ')

/*updateMasterMpIfErrorStateMain_Execute_POIFLOAD_DOOS*/

		UPDATE POIFLOAD_DOOS /* 인터페이스 두중 발주내역 */
		SET BUYER_ITEM_NO = #{BUYER_ITEM_NO}
		WHERE 1=1
		AND COM_CODE      = #{BUYER}
		AND LEGACY_PO_NO  = #{LEGACY_PO_NO}
		AND LEGACY_PO_SEQ = NVL(#{LEGACY_PO_SEQ},' ')

/*updateMasterMpIfErrorStateMain_Execute_IF_PROGRESS*/

		UPDATE IF_PROGRESS /* 오류 현황 메인 */
		SET IF_FLAG   = 'C'
		WHERE 1=1
		AND BUYER     = #{BUYER}
		AND LEGACY_NO = #{LEGACY_PO_NO}

/*updateMasterMpIfErrorStateMain_Partial_Po_IF_PODT*/

		UPDATE IF_PODT /* 인터페이스 주문상세내역 */
		SET IF_FLAG       = 'Z'
		WHERE 1=1
		AND BUYER         = #{BUYER}
		AND LEGACY_PO_NO  = #{LEGACY_PO_NO}
		AND LEGACY_PO_SEQ = NVL(#{LEGACY_PO_SEQ},' ')
		AND BUYER_ITEM_NO = NVL(#{BUYER_ITEM_NO},' ')

/*updateMasterMpIfErrorStateMain_Partial_Po_IF_PROGRESS*/

		UPDATE IF_PROGRESS /* 오류 현황 메인 */
		SET IF_FLAG   = 'C'
		WHERE 1=1
		AND BUYER     = #{BUYER}
		AND LEGACY_NO = #{LEGACY_PO_NO}
		AND GUBUN     = 'PO'

/*updateMasterMpIfErrorStateMain_Save_IF_PODT*/

		UPDATE IF_PODT /* 인터페이스 주문상세내역 */
		SET CHANGE_USER_ID    = #{st_user_id}
		  , CHANGE_DATE       = TO_CHAR(SYSDATE,'YYYYMMDD')
		  , CHANGE_TIME       = TO_CHAR(SYSDATE,'HH24MISS')
		  , AGENT             = #{AGENT}
		  , DOC_TYPE          = #{DOC_TYPE}
		  , CONTRACT_NO       = #{CONTRACT_NO}
		  , CONTRACT_SEQ      = #{CONTRACT_SEQ}
		  , PURCHASER_USER_ID = #{PURCHASER_USER_ID}
		  , ADD_DATE          = #{ADD_DATE}
		  , RD_DATE           = #{RD_DATE_IF}
		  , DATE_CHANGE_HIST  = SUBSTRB(SUBSTRB(DATE_CHANGE_HIST,1,350)||(CASE WHEN ADD_DATE != #{ADD_DATE} THEN '@ADD_DATE:'||ADD_DATE||'#'||CHANGE_USER_ID END)||(CASE WHEN RD_DATE != #{RD_DATE_IF} THEN '@RD_DATE:'||RD_DATE||'#'||CHANGE_USER_ID END),1,400)
		  , BUYER_ITEM_NO     = NVL(TRIM(#{BUYER_ITEM_NO}),' ')
		  , UNIT_PRICE        = NVL(#{UNIT_PRICE_IF},UNIT_PRICE)
		  , ITEM_AMT          = NVL(#{UNIT_PRICE_IF},UNIT_PRICE) * ITEM_QTY
		  , DELY_TO_LOCATION = #{DELY_TO_LOCATION}
		WHERE 1=1
		AND BUYER             = #{BUYER}
		AND LEGACY_PO_NO      = NVL(#{LEGACY_PO_NO},' ')
		AND LEGACY_PO_SEQ     = NVL(#{LEGACY_PO_SEQ},' ')
		AND BUYER_ITEM_NO     = NVL(#{ORG_BUYER_ITEM_NO}, ' ')


UPDATE IF_PODT /* 인터페이스 주문상세내역 */
SET IF_FLAG       = 'D'
  , CANCEL_DATE   = SYSDATE
  , CANCEL_RSON   = #{st_cancel_remark}
  , CANCEL_ID     = #{st_user_id}
WHERE 1=1
AND BUYER         = #{BUYER}
AND LEGACY_PO_NO  = #{LEGACY_PO_NO}
AND LEGACY_PO_SEQ = NVL(#{LEGACY_PO_SEQ},' ')


UPDATE IF_PODT 
SET GW_NO       = #{GW_NO}
WHERE 1=1
AND BUYER         = #{BUYER}
AND LEGACY_PO_NO  = #{LEGACY_PO_NO}
AND LEGACY_PO_SEQ = #{LEGACY_PO_SEQ}
